function SelectElectrodes(inputs)

% Function to select the data from a specific set of electrodes (using a list or a picture)
% It uses the output generated by "QualityControl_Manual"
% (revised October 2026: the three input arguments -file_input, file_label, option- were overwritten inside the function and never used;
%  now, like the other stages, it accepts an optional structure "inputs" to overwrite the INPUTS/PARAMETERS below, see "override_inputs")

if ~parameter_set('active'), clc; end; close all;      % (revised October 2026) no "clc" while "run_pipeline" runs (it would erase its progress messages)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
system = 3;                 % =1, Ubuntu; =2, Yang's PC; =3, Yang's MacBook; =0, do not modify the MATLAB path (e.g., test harness)
if nargin < 1, inputs = struct(); end                                       % no inputs provided -> use the values defined in the code
if isfield(inputs, 'system'), system = inputs.system; end                   % the system can also be provided as an input
switch system
    case 0      % the MATLAB path is set up by the caller
        delimiter = filesep;
    case 1      % Anlysis PCP - Ubuntu
        addpath(genpath('/home/cortex/Documents/Yang'));
        delimiter = '/';
    case 2      % Yang's PC - GitHub
        addpath(genpath('C:\Users\Yang\OneDrive - Harvard University\Documents\GitHub\MEA-analysis\'));
        delimiter = '\\';
    case 3      % Yang's MacBook
        addpath(genpath('/Users/sungminyang/Documents/GitHub/CellCircuit'));
        delimiter = '/';
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%   INPUTS   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

folder = '/path/to/recording_folder';
file_data = 'recording_name'; 
organoid_label = 'org3';      

option = 2;                     % =1, cropping based on electrode map in an excel file (from 3Brain software)
                                % =2, cropping based on manual drawing (picture)

file_excel = '';    ellipse_cropped = nan;      CROPPING_SAFETY = 1.10;     % default values (defined for both options, so that any of them can be provided as input)
switch option
    case 1                      % cropping based on electrode map in an excel file (from 3Brain software)

        file_excel = 'electrode_map';

    case 2                      % cropping based on manual drawing (picture)

        x0 = 26;                % coordinate 'x' of the center, in pixels
        y0 = 18;                % coordinate 'y' of the center, in pixels
        radiusx = 16;            % radius in the axis 'x', in pixels
        radiusy = 16;            % radius in the axis 'y', in pixels
        
        CROPPING_SAFETY = 1.10; % proportion of the actual ellipse to be cropped (default: 1.10)
        ellipse_cropped = [x0 y0 radiusx radiusy];  % ellipse to be cropped
end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%   OUTPUT   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% save the following variables in the file sprintf('%s\\%s_QCmanual.mat',folder,file_data):
%   - structure array spikeTimestamp (same structure than the output generated by "ShapeSpikeTrainData"), ONLY with cropped good clusters   

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%   PARAMETERS   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

K_MSEC_SEC = 1/1000;                        % factor to rescale from msec to sec
SHEET = 4;                                  % sheet within the excel file to read the coordinates of the selected electrodes
COLUMN = 4;                                 % column within the excel file table that contains the channel id
ROW = 5;                                    % row witin the excel file table that contains the first data point
MATRIX_SIZE = 64;                           % dimension of the electrode array (64*64=4096)

apply_parameters('SelectElectrodes');                                       % (revised October 2026) values of the parameter set of "run_pipeline", if any (see "pipeline_parameters")
override_inputs(inputs);                    % overwrite the INPUTS / PARAMETERS above with the ones provided as input (if any)
                                            % (if "option" is provided, also provide "file_excel" or "ellipse_cropped", since they are defined above depending on "option")

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%     Load data       %%%

file_input = sprintf('%s%s%s_QCmanual.mat', folder, delimiter, file_data);
load(file_input,'spikeTimestamp','rec_conditions','minimum_activity','idx_abnormalActivity','good_cluster','n_discarded_HS','n_discarded_manual','n_clusterOriginal','n_discarded_QCgeneral');   
file_output = sprintf('%s%s%s_%s_QCmanual.mat', folder, delimiter, file_data, organoid_label);

switch option           
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

    case 1              % The electrode label for selection are provided by the 3Brain software in an excel file

        file_label = sprintf('%s%s%s.xlsx', folder, delimiter, file_excel);
        metadata = readcell(file_label,'UseExcel',true,'Sheet',SHEET);
        label = metadata(ROW:size(metadata,1),COLUMN);                      % id of the electrodes to be selected
        n_electrodesTotal = size(spikeTimestamp,2);                         % total number of good clusters after QC

        n_electrodes = size(label,1);                                       % total number of electrodes to be selected
        selected = zeros(n_electrodesTotal,1);
        for i=1:n_electrodes                                                % across all electrodes to be selected
            if contains(string(label(i)),"Ch")                              % in the excel file, the id has the format "Ch XX, YY"
                aux1 = regexp(label(i),' ','split');
                aux2 = regexp(aux1{1,1}{1,2},',','split');
                pos_x = str2double(aux2(1));                                % position x of the electrode i
                pos_y = str2double(aux2(2));                                % position y of the electrode i

                for k=1:n_electrodesTotal                                   % across all good clusters
                    x = spikeTimestamp(k).positionXY(1);                    % position x of the cluster k    
                    y = spikeTimestamp(k).positionXY(2);                    % position y of the cluster k
                    if pos_x == x && pos_y == y                             % electrode i and cluster k are in the same position
                        selected(k)=1;                                      % label electrode k as to be selected
                    end
                end
            end
        end
        spikeTimestamp_BeforeCropping = spikeTimestamp;
        spikeTimestamp(selected==0) = [];                                   % eliminate the clusters that were not selected (all at once)

        %% Plot the electrode map

        map = nan(MATRIX_SIZE,MATRIX_SIZE); 
        for i=1:n_electrodesTotal                                           % across all good clusters 
            pos_x = spikeTimestamp_BeforeCropping(i).positionXY(1)+1;       % position x (+1, to make it in [1: MATRIX_SIZE])
            pos_y = spikeTimestamp_BeforeCropping(i).positionXY(2)+1;       % position y (+1, to make it in [1: MATRIX_SIZE])
            label=1;                                                        % by default, label=1
            if ~selected(i)                                                 % if cluster i was NOT selected
               label = -1;                                                  % the non-selected clusters are labeled =-1
            end
            map(MATRIX_SIZE - pos_y + 1,pos_x) = label;                     % =nan, not an active electrode; =1, selected active electrode; =-1, non-selected active electrode
        end

        figure(1)                                                           % electrode map showing the cropped electrodes
        h = heatmap(map,'XDisplayLabels',NaN*ones(size(map,1),1),'YDisplayLabels',NaN*ones(size(map,1),1),'Colormap',cool,'ColorLimits',[0 1]);
        h.MissingDataColor = [0.5 0.5 0.5];        title('Electrode map (=1, cropped electrodes)')
        save(file_output,'spikeTimestamp_BeforeCropping','spikeTimestamp','rec_conditions','minimum_activity','idx_abnormalActivity','good_cluster','n_discarded_HS','n_discarded_manual','file_excel','option','n_clusterOriginal','n_discarded_QCgeneral');   

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    case 2              % cropping based on manual drawing
    
        %% Cropped the electrode map based on a picture
    
        n_cluster = size(spikeTimestamp,2);                                 % total number of clusters    
        picture_cluster = zeros(n_cluster,1);                               % clusters within the picture 
        ellipse = @(x,y,x0,y0,radius_x,radius_y) ((x-x0)/radius_x)^2 + ((y-y0)/radius_y)^2;  % define the ellipse
   
        if isnan(ellipse_cropped)
            error('\n The ellipse for cropping has not been defined!!!')
        else                                                                % the dimensions of the cropping ellipse have been definied
            x0 = ellipse_cropped(1);                                        % coordinate 'x' of the center, in pixels
            y0 = ellipse_cropped(2);                                        % coordinate 'y' of the center, in pixels
            radiusx = ellipse_cropped(3);                                   % radius in the axis 'x', in pixels
            radiusy = ellipse_cropped(4);                                   % radius in the axis 'y', in pixels
        end
   
        for i=1:n_cluster                                                   % across all clusters
            pos_x = spikeTimestamp(i).positionXY(1)+1;                      % position x (+1, to make it in [1: MATRIX_SIZE])
            pos_y = spikeTimestamp(i).positionXY(2)+1;                      % position y (+1, to make it in [1: MATRIX_SIZE])
            if ellipse(pos_x,pos_y,x0,y0,radiusx*CROPPING_SAFETY,radiusy*CROPPING_SAFETY) <= 1       % if the electrode is within the ellipse
                picture_cluster(i) = 1;                                     % the cluster i is labeled =1    
            end
        end
        spikeTimestamp_BeforeCropping = spikeTimestamp;                     % original/initial "spikeTimestamp" variable

        %% Discard the clusters outside the ellipse

        discarded_cluster = ~picture_cluster;                               % identify all the clusters to be discarded     
        idx_discarded = find(discarded_cluster>0);                          % index of clusters to be discarded
        n_discarded = numel(idx_discarded);                                 % total number of clusters to be discarded
        fprintf('Total number of clusters to be discarded: %g (out of %g)\n', n_discarded, n_cluster);
        spikeTimestamp(idx_discarded) = [];                                 % eliminate the data for the clusters outside of the ellipse (all at once; the unused n x n cell array "discarded_signal" was removed)

        %% Plot the electrode map

        map = nan(MATRIX_SIZE,MATRIX_SIZE); 
        map_cropped = nan(MATRIX_SIZE,MATRIX_SIZE); 
        for i=1:n_cluster                                                   % across all clusters 
            pos_x = spikeTimestamp_BeforeCropping(i).positionXY(1)+1;       % position x (+1, to make it in [1: MATRIX_SIZE])
            pos_y = spikeTimestamp_BeforeCropping(i).positionXY(2)+1;       % position y (+1, to make it in [1: MATRIX_SIZE])
            label=1;                                                        % the default label for cluster i is =1 
            if ~picture_cluster(i)                                          % outside of the ellipse
               label = -1;                                                  % change the label as to-be-discarded
            else                                                            % within the ellipse
               map_cropped(MATRIX_SIZE - pos_y + 1,pos_x) = label;          % identify the electrode to be cropped
            end
            map(MATRIX_SIZE - pos_y + 1,pos_x) = label;                     % =nan, not an active electrode; =1, active electrode inside the ellipse; =-1, active electrode outside the ellipse
        end
         
        figure(1)                                                           % electrode map showing the cropped electrodes vs discarded electrodes
        h = heatmap(map,'XDisplayLabels',NaN*ones(size(map,1),1),'YDisplayLabels',NaN*ones(size(map,1),1),'Colormap',cool);        h.MissingDataColor = [0.5 0.5 0.5];        title('Electrode map (=1, cropped electrodes)')
        pos = get(gca, 'Position');
        xapf = @(x,pos,xl) pos(3)*(x-min(xl))/diff(xl)+pos(1);              % 'x' Annotation Position Function
        yapf = @(y,pos,yl) pos(4)*(y-min(yl))/diff(yl)+pos(2);              % 'y' Annotation Position Function
        pos = gca().Position;
        xx=xlim;        xl(1) = str2double(xx(1)); xl(2) = str2double(xx(2));
        yy=ylim;        yl(1) = str2double(yy(1)); yl(2) = str2double(yy(2));
        annotation('ellipse', [xapf(x0-radiusx,pos,xl) yapf(y0-radiusy,pos,yl) radiusx*2*pos(3)/diff(xl) radiusy*2*pos(4)/diff(yl)],"Color","white","LineWidth",1, "LineStyle","--");

        figure(2)                                                           % electrode map (showing only the cropped electrodes)
        h2 = heatmap(map_cropped,'XDisplayLabels',NaN*ones(size(map_cropped,1),1),'YDisplayLabels',NaN*ones(size(map_cropped,1),1),'Colormap',cool,'ColorLimits',[0 1]);        h2.MissingDataColor = [0.5 0.5 0.5];        title('Cropped Electrodes (=1)')
        save(file_output,'spikeTimestamp_BeforeCropping','spikeTimestamp','rec_conditions','minimum_activity','idx_abnormalActivity','good_cluster','n_discarded_HS','n_discarded_manual','ellipse_cropped','option','n_clusterOriginal','n_discarded_QCgeneral');   

end     % end of the switch  

fclose('all');        
end

